--1. Revenue generated by each channel [paid search and paid social]
SELECT channel, SUM(revenue_first_90_days) AS total_revenue
FROM signups_clean
GROUP BY channel;


--2.1 Most popular campaign [prospecting_video]
SELECT channel, campaign, COUNT(user_id) AS signups
FROM signups_clean
WHERE source_type = 'subscribed'
GROUP BY channel, campaign
ORDER BY signups DESC;

-- 2.2
SELECT channel, campaign,
       COUNT(*) AS signups,
       COUNT(*) FILTER (WHERE subscribing) AS paying_customers
FROM signups_clean
WHERE campaign IS NOT NULL
GROUP BY channel, campaign
ORDER BY paying_customers DESC;

-- Total subscribers from campaign
SELECT COUNT(*) FILTER (WHERE subscribing) AS paid_campaign_customers
FROM signups_clean
WHERE campaign IS NOT NULL
ORDER BY paid_campaign_customers DESC;

--3. Lowest cost per signup
WITH spend AS (
    SELECT channel, campaign, SUM(spend) AS total_spend
    FROM ad_spend_clean
    GROUP BY channel, campaign
),
su AS (
    SELECT channel, campaign, COUNT(*) AS signups
    FROM signups_clean
    WHERE campaign IS NOT NULL
    GROUP BY channel, campaign
)
SELECT s.channel, s.campaign, s.total_spend, su.signups,
       ROUND(s.total_spend / NULLIF(su.signups, 0), 2) AS cost_per_signup
FROM spend s
JOIN su USING (channel, campaign)
ORDER BY cost_per_signup;

--4. Does a cheaper channel = less revenue?
WITH spend AS (
    SELECT channel, campaign, SUM(spend) AS total_spend
    FROM ad_spend_clean
    GROUP BY channel, campaign
),
outcomes AS (
    SELECT channel, campaign,
           COUNT(*) AS signups,
           COUNT(*) FILTER (WHERE subscribing) AS paying_customers
    FROM signups_clean
    WHERE campaign IS NOT NULL
    GROUP BY channel, campaign
)
SELECT s.channel, s.campaign,
       ROUND(s.total_spend / NULLIF(o.signups, 0), 2) AS cost_per_signup,
       ROUND(100.0 * o.paying_customers / NULLIF(o.signups, 0), 2) AS customer_conversion_rate,
       ROUND(s.total_spend / NULLIF(o.paying_customers, 0), 2) AS cost_per_customer
FROM spend s
JOIN outcomes o USING (channel, campaign)
ORDER BY cost_per_signup;
